window.addEventListener('load', () => { const loader = document.getElementById('loader'); setTimeout(() => { loader.classList.add('hidden'); document.body.style.overflow = ''; }, 1600); }); document.body.style.overflow = 'hidden'; (function initCursor() { const dot = document.getElementById('cursorDot'); const ring = document.getElementById('cursorRing'); if (!dot || !ring) return; let mouseX = 0, mouseY = 0; let ringX = 0, ringY = 0; document.addEventListener('mousemove', (e) => { mouseX = e.clientX; mouseY = e.clientY; dot.style.left = mouseX + 'px'; dot.style.top = mouseY + 'px'; }); function animateRing() { ringX += (mouseX - ringX) * 0.12; ringY += (mouseY - ringY) * 0.12; ring.style.left = ringX + 'px'; ring.style.top = ringY + 'px'; requestAnimationFrame(animateRing); } animateRing(); document.addEventListener('mouseleave', () => { dot.style.opacity = '0'; ring.style.opacity = '0'; }); document.addEventListener('mouseenter', () => { dot.style.opacity = '1'; ring.style.opacity = '1'; }); })(); (function initNavbar() { const navbar = document.getElementById('navbar'); const navLinks = document.querySelectorAll('.nav-link[data-section]'); const onScroll = () => { if (window.scrollY > 50) { navbar.classList.add('scrolled'); } else { navbar.classList.remove('scrolled'); } highlightActiveLink(); }; window.addEventListener('scroll', onScroll, { passive: true }); function highlightActiveLink() { const scrollPos = window.scrollY + 120; navLinks.forEach(link => { const sectionId = link.dataset.section; const section = document.getElementById(sectionId); if (!section) return; const top = section.offsetTop; const bottom = top + section.offsetHeight; if (scrollPos >= top && scrollPos < bottom) { navLinks.forEach(l => l.classList.remove('active')); link.classList.add('active'); } }); } })(); (function initHamburger() { const btn = document.getElementById('hamburger'); const navLinks = document.getElementById('navLinks'); if (!btn || !navLinks) return; btn.addEventListener('click', () => { const isOpen = navLinks.classList.toggle('open'); btn.classList.toggle('open', isOpen); btn.setAttribute('aria-expanded', isOpen); document.body.style.overflow = isOpen ? 'hidden' : ''; }); navLinks.querySelectorAll('.nav-link').forEach(link => { link.addEventListener('click', () => { navLinks.classList.remove('open'); btn.classList.remove('open'); document.body.style.overflow = ''; }); }); })(); (function initTyping() { const el = document.getElementById('typingText'); if (!el) return; const roles = [ 'Full-Stack Developer', 'Android App Developer', 'Software QA Tester', 'UI/UX Enthusiast', 'Open Source Contributor', 'Cloud Architect', 'Problem Solver', ]; let roleIndex = 0; let charIndex = 0; let isDeleting = false; let pause = false; function type() { if (pause) return; const current = roles[roleIndex]; if (isDeleting) { el.textContent = current.slice(0, charIndex - 1); charIndex--; } else { el.textContent = current.slice(0, charIndex + 1); charIndex++; } let delay = isDeleting ? 60 : 100; if (!isDeleting && charIndex === current.length) { delay = 2000; isDeleting = true; } else if (isDeleting && charIndex === 0) { isDeleting = false; roleIndex = (roleIndex + 1) % roles.length; delay = 400; } setTimeout(type, delay); } type(); })(); (function initScrollReveal() { const elements = document.querySelectorAll('[class*="reveal-"]'); const observer = new IntersectionObserver((entries) => { entries.forEach(entry => { if (entry.isIntersecting) { entry.target.classList.add('in-view'); observer.unobserve(entry.target); } }); }, { threshold: 0.12, rootMargin: '0px 0px -40px 0px', }); elements.forEach(el => observer.observe(el)); })(); (function initSkillBars() { const skillItems = document.querySelectorAll('.skill-item[data-level]'); const observer = new IntersectionObserver((entries) => { entries.forEach(entry => { if (entry.isIntersecting) { const item = entry.target; const fill = item.querySelector('.skill-fill'); const level = item.dataset.level; if (fill) { setTimeout(() => { fill.style.width = level + '%'; }, 200); } observer.unobserve(item); } }); }, { threshold: 0.3 }); skillItems.forEach(el => observer.observe(el)); })(); (function initCounters() { const counters = document.querySelectorAll('.stat-num[data-target]'); const observer = new IntersectionObserver((entries) => { entries.forEach(entry => { if (!entry.isIntersecting) return; const el = entry.target; const target = parseInt(el.dataset.target, 10); const dur = 1800; const step = dur / target; let current = 0; const interval = setInterval(() => { current++; el.textContent = current; if (current >= target) clearInterval(interval); }, step); observer.unobserve(el); }); }, { threshold: 0.5 }); counters.forEach(el => observer.observe(el)); })(); (function initProjectFilter() { const filterBtns = document.querySelectorAll('.filter-btn'); const projectCards = document.querySelectorAll('.project-card[data-category]'); filterBtns.forEach(btn => { btn.addEventListener('click', () => { filterBtns.forEach(b => b.classList.remove('active')); btn.classList.add('active'); const filter = btn.dataset.filter; projectCards.forEach(card => { const category = card.dataset.category; const match = filter === 'all' || category === filter; if (match) { card.classList.remove('hidden'); card.style.animation = 'none'; void card.offsetWidth; card.style.animation = 'fadeInUp .4s ease forwards'; } else { card.classList.add('hidden'); } }); }); }); const style = document.createElement('style'); style.textContent = ` @keyframes fadeInUp { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } } `; document.head.appendChild(style); })(); (function initCertFilter() { const filterBtns = document.querySelectorAll('.cert-filter-btn'); const certCards = document.querySelectorAll('.cert-card[data-category]'); filterBtns.forEach(btn => { btn.addEventListener('click', () => { filterBtns.forEach(b => b.classList.remove('active')); btn.classList.add('active'); const filter = btn.dataset.filter; certCards.forEach(card => { const category = card.dataset.category; const match = filter === 'all' || category === filter; if (match) { card.classList.remove('hidden'); card.style.animation = 'none'; void card.offsetWidth; card.style.animation = 'fadeInUp .4s ease forwards'; } else { card.classList.add('hidden'); } }); }); }); })(); (function initTimelineTabs() { const tabs = document.querySelectorAll('.tl-tab'); const panels = document.querySelectorAll('.timeline-panel'); tabs.forEach(tab => { tab.addEventListener('click', () => { tabs.forEach(t => t.classList.remove('active')); tab.classList.add('active'); const target = tab.dataset.tab; panels.forEach(panel => { panel.classList.toggle('active', panel.id === target); }); const revealEls = document.querySelectorAll(`#${target} [class*="reveal-"]`); revealEls.forEach(el => { if (!el.classList.contains('in-view')) { el.classList.add('in-view'); } }); }); }); })(); (function initCertFilter() { const filterBtns = document.querySelectorAll('.cert-filter-btn'); const certCards = document.querySelectorAll('.cert-card[data-category]'); filterBtns.forEach(btn => { btn.addEventListener('click', () => { filterBtns.forEach(b => b.classList.remove('active')); btn.classList.add('active'); const filter = btn.dataset.filter; certCards.forEach(card => { const category = card.dataset.category; const match = filter === 'all' || category === filter; if (match) { card.classList.remove('hidden'); card.style.animation = 'none'; void card.offsetWidth; card.style.animation = 'fadeInUp .4s ease forwards'; } else { card.classList.add('hidden'); } }); }); }); })(); (function initContactForm() { const form = document.getElementById('contactForm'); if (!form) return; const submitBtn = document.getElementById('submitBtn'); const btnText = submitBtn.querySelector('.btn-text'); const btnLoading = submitBtn.querySelector('.btn-loading'); const formAlert = document.getElementById('formAlert'); const fields = { name: { el: document.getElementById('name'), error: document.getElementById('nameError') }, email: { el: document.getElementById('email'), error: document.getElementById('emailError') }, subject: { el: document.getElementById('subject'), error: document.getElementById('subjectError') }, message: { el: document.getElementById('message'), error: document.getElementById('messageError') }, }; const rules = { name: { min: 2, msg: 'Name must be at least 2 characters.' }, email: { regex: /^[^\s@]+@[^\s@]+\.[^\s@]+$/, msg: 'Please enter a valid email address.' }, subject: { min: 4, msg: 'Subject must be at least 4 characters.' }, message: { min: 15, msg: 'Message must be at least 15 characters.' }, }; function validateField(name) { const { el, error } = fields[name]; const val = el.value.trim(); let msg = ''; if (!val) { msg = 'This field is required.'; } else if (rules[name].regex && !rules[name].regex.test(val)) { msg = rules[name].msg; } else if (rules[name].min && val.length < rules[name].min) { msg = rules[name].msg; } error.textContent = msg; el.classList.toggle('error', !!msg); return !msg; } Object.keys(fields).forEach(name => { const { el } = fields[name]; el.addEventListener('blur', () => validateField(name)); el.addEventListener('input', () => { if (el.classList.contains('error')) validateField(name); }); }); form.addEventListener('submit', async (e) => { e.preventDefault(); const valid = Object.keys(fields).map(validateField).every(Boolean); if (!valid) return; btnText.hidden = true; btnLoading.hidden = false; submitBtn.disabled = true; formAlert.hidden = true; try { const data = new FormData(form); const response = await fetch('contact.php', { method: 'POST', body: data, }); const result = await response.json(); showAlert(result.success ? 'success' : 'error', result.message); if (result.success) { form.reset(); Object.values(fields).forEach(({ el }) => el.classList.remove('error')); } } catch (err) { showAlert('error', '⚠️ Network error. Please try again or email me directly.'); console.error('Contact form error:', err); } finally { btnText.hidden = false; btnLoading.hidden = true; submitBtn.disabled = false; } }); function showAlert(type, message) { formAlert.hidden = false; formAlert.className = 'form-alert ' + (type === 'success' ? 'success' : 'error-alert'); formAlert.textContent = message; setTimeout(() => { formAlert.hidden = true; }, 6000); } })(); (function initBackToTop() { const btn = document.getElementById('backToTop'); if (!btn) return; window.addEventListener('scroll', () => { btn.classList.toggle('visible', window.scrollY > 400); }, { passive: true }); btn.addEventListener('click', () => { window.scrollTo({ top: 0, behavior: 'smooth' }); }); })(); (function setFooterYear() { const el = document.getElementById('footerYear'); if (el) el.textContent = new Date().getFullYear(); })(); (function initSmoothScroll() { document.querySelectorAll('a[href^="#"]').forEach(anchor => { anchor.addEventListener('click', (e) => { const target = document.querySelector(anchor.getAttribute('href')); if (target) { e.preventDefault(); const offset = 80; const top = target.getBoundingClientRect().top + window.scrollY - offset; window.scrollTo({ top, behavior: 'smooth' }); } }); }); })(); (function initHeroParallax() { const hero = document.querySelector('.hero'); const avatar = document.getElementById('heroAvatar'); if (!hero || !avatar) return; hero.addEventListener('mousemove', (e) => { const { left, top, width, height } = hero.getBoundingClientRect(); const x = ((e.clientX - left) / width - 0.5) * 14; const y = ((e.clientY - top) / height - 0.5) * 14; avatar.style.transform = `translate(${x}px, ${y}px)`; }); hero.addEventListener('mouseleave', () => { avatar.style.transform = 'translate(0, 0)'; avatar.style.transition = 'transform 0.6s ease'; }); })();